static lstr L1094 = {0, 1073, "// std/coroutine: Co.resume runs a generator to its next yield, and Co.send runs\012// a coroutine to its next yield with an input.\012//\012// The compiler turns `Co.resume(mutable g)` into resumeGenerator and\012// `Co.send(mutable g, input)` into resumeCoroutine.\012\012import * as Internal from \"std/internal/coroutine\"\012\012export enum Step<Out> derives Show, Equatable {\012  Yielded(value: Out)\012  Done\012  Panicked(message: string)\012}\012\012export function resumeGenerator<T, effect E>(\012  mutable g: Generator<T> uses E,\012): Step<T> uses E, alloc {\012  return readStep(Internal.next(mutable g))\012}\012\012export function resumeCoroutine<In, Out, effect E>(\012  mutable g: Coroutine<In, Out> uses E,\012  input: In,\012): Step<Out> uses E, alloc {\012  return readStep(Internal.resume(mutable g, input))\012}\012\012// readStep reads the outcome of one resume: a value, the end, or a panic.\012function readStep<T>(next: Option<T>): Step<T> from next uses alloc {\012  if (next is Some(value)) {\012    return Step.Yielded(value)\012  }\012  if (Internal.panicked()) {\012    return Step.Panicked(Internal.panicMessage())\012  }\012  return Step.Done\012}\012"};
