static lstr L1098 = {0, 3308, "// std/array: helpers over Array. The functions that need the compiler are built in.\012\012import * as Arrays from \"std/array\"\012\012export function map<T, U, effect E>(\012  items: Array<T>,\012  change: (value: T) => U uses E,\012): Array<U> uses alloc, E {\012  let result: Array<U> = Arrays.withCapacity(Arrays.length(items))\012  for (const item of items) {\012    Arrays.push(mutable result, change(item))\012  }\012  return result\012}\012\012export function slice<T>(items: Array<T>, start: int, finish: int): Option<Array<T>> uses alloc {\012  // A range outside the array has no slice.\012  if (start < 0 || finish > Arrays.length(items) || start > finish) {\012    return None\012  }\012  let result: Array<T> = Arrays.withCapacity(finish - start)\012  for (let index = start; index < finish; index++) {\012    Arrays.push(mutable result, copy(items[index]))\012  }\012  return Some(result)\012}\012\012export function pop<T>(mutable items: Array<T>): Option<T> uses alloc {\012  const count = Arrays.length(items)\012  if (count == 0) {\012    return None\012  }\012  // The last item is copied out before the array shrinks, so a shared array is copied once.\012  const last = copy(items[count - 1])\012  Arrays.truncate(mutable items, count - 1)\012  return Some(last)\012}\012\012export function indexOf<T: Equatable>(items: Array<T>, wanted: T): Option<int> {\012  for (let index = 0; index < Arrays.length(items); index++) {\012    if (items[index] == wanted) {\012      return Some(index)\012    }\012  }\012  return None\012}\012\012export function contains<T: Equatable>(items: Array<T>, wanted: T): bool {\012  return indexOf(items, wanted) is Some(_)\012}\012\012export function reverse<T>(mutable items: Array<T>) uses alloc {\012  let low = 0\012  let high = Arrays.length(items) - 1\012  while (low < high) {\012    const held = copy(items[low])\012    items[low] = copy(items[high])\012    items[high] = held\012    low++\012    high--\012  }\012}\012\012export function sort<T: Ordered>(mutable items: Array<T>) uses alloc {\012  sortBy(mutable items, (first: T, second: T) => Ordered.compare(first, second))\012}\012\012export function sortBy<T, effect E>(\012  mutable items: Array<T>,\012  compare: (first: T, second: T) => Ordering uses E,\012) uses alloc, E {\012  const count = Arrays.length(items)\012  if (count < 2) {\012    return\012  }\012  // Bottom-up merge sort: runs of `width` items are merged pairwise. A merge takes\012  // from the left run on a tie, which keeps equal items in their order.\012  let buffer: Array<T> = Arrays.withCapacity(count)\012  for (const item of items) {\012    Arrays.push(mutable buffer, copy(item))\012  }\012  let width = 1\012  while (width < count) {\012    for (let start = 0; start < count; start += width * 2) {\012      const middle = pickSmaller(start + width, count)\012      const finish = pickSmaller(start + width * 2, count)\012      let left = start\012      let right = middle\012      for (let target = start; target < finish; target++) {\012        if (\012          right >= finish ||\012            (left < middle && compare(items[left], items[right]) != Ordering.Greater)\012        ) {\012          buffer[target] = copy(items[left])\012          left++\012        } else {\012          buffer[target] = copy(items[right])\012          right++\012        }\012      }\012    }\012    for (let index = 0; index < count; index++) {\012      items[index] = copy(buffer[index])\012    }\012    width *= 2\012  }\012}\012\012function pickSmaller(first: int, second: int): int {\012  if (first < second) {\012    return first\012  }\012  return second\012}\012"};
