static lstr L1100 = {0, 1027, "// std/char: code points and ASCII classes. The conversion functions are built into the compiler.\012//\012// The classes cover ASCII only: a character above U+007F is in none of them, and\012// isWhitespace is true for the six ASCII white space characters that Str.trim removes.\012\012import * as Char from \"std/char\"\012\012export function isDigit(character: char): bool {\012  const code = Char.code(character)\012  return code >= 48 && code <= 57\012}\012\012export function isUpper(character: char): bool {\012  const code = Char.code(character)\012  return code >= 65 && code <= 90\012}\012\012export function isLower(character: char): bool {\012  const code = Char.code(character)\012  return code >= 97 && code <= 122\012}\012\012export function isLetter(character: char): bool {\012  return isUpper(character) || isLower(character)\012}\012\012export function isAlphanumeric(character: char): bool {\012  return isLetter(character) || isDigit(character)\012}\012\012export function isWhitespace(character: char): bool {\012  const code = Char.code(character)\012  return code == 32 || (code >= 9 && code <= 13)\012}\012"};
