static lstr L1477 = {0, 6831, "// std/internal/thread (D111 item 4). POSIX threads for std/thread; only a\012// program in thread mode (NARRA_THREADS) includes this text.\012//\012// narra_thread_start marks the captures of the thread function shared, then\012// runs the function on a new thread with an 8 MiB stack, the size of the main\012// thread's. The new thread takes a heap, calls the function, runs the exit of\012// its event loop (D109 item 6) when it started tasks, releases the\012// environment and gives the heap back. The thread is a number to Narra code:\012// its pthread_t, which narra_thread_join waits for.\012#include <errno.h>\012\012struct narra_env;\012\012typedef struct narra_thread_work {\012  void (*fn)(struct narra_env* env);\012  struct narra_env* env;\012  void (*release)(struct narra_env* env);\012} narra_thread_work;\012\012static void* narra_thread_main(void* argument) {\012  narra_thread_work work = *(narra_thread_work*)argument;\012  free(argument);\012  narra_heap_enter();\012  work.fn(work.env);\012  void (*loop_exit)(void) = __atomic_load_n(&narra_loop_exit_hook, __ATOMIC_ACQUIRE);\012  if (loop_exit) loop_exit();\012  work.release(work.env);\012  // The drop and share worklists of this thread are plain memory that ends with it.\012  free(narra_pend);\012  narra_pend = NULL;\012  narra_pend_cap = 0;\012  free(narra_shares);\012  narra_shares = NULL;\012  narra_shares_cap = 0;\012  narra_heap_leave();\012  __atomic_fetch_sub(&narra_threads_running, 1, __ATOMIC_RELEASE);\012  return NULL;\012}\012\012static int64_t narra_thread_start(\012  void (*fn)(struct narra_env*),\012  struct narra_env* env,\012  void (*share)(struct narra_env*),\012  void (*release)(struct narra_env*)\012) {\012  share(env);\012  // Plain malloc: the new thread frees it before it allocates.\012  narra_thread_work* work = malloc(sizeof(narra_thread_work));\012  if (!work) narra_panic(\"runtime\", \"out of memory\");\012  work->fn = fn;\012  work->env = env;\012  work->release = release;\012  pthread_attr_t attributes;\012  pthread_attr_init(&attributes);\012  pthread_attr_setstacksize(&attributes, (size_t)8 << 20);\012  __atomic_fetch_add(&narra_threads_running, 1, __ATOMIC_ACQ_REL);\012  pthread_t thread;\012  int failed = pthread_create(&thread, &attributes, narra_thread_main, work);\012  pthread_attr_destroy(&attributes);\012  if (failed) {\012    __atomic_fetch_sub(&narra_threads_running, 1, __ATOMIC_ACQ_REL);\012    narra_panic(\"runtime\", \"cannot start a thread\");\012  }\012  return (int64_t)(uintptr_t)thread;\012}\012\012static void narra_thread_join(int64_t thread) {\012  pthread_join((pthread_t)(uintptr_t)thread, NULL);\012}\012\012// The cores online, for std/parallel. macOS hides the sysconf name under\012// _POSIX_C_SOURCE; its value there is 58.\012#if !defined(_SC_NPROCESSORS_ONLN) && defined(__APPLE__)\012#define _SC_NPROCESSORS_ONLN 58\012#endif\012static int64_t narra_thread_cores(void) {\012#ifdef _SC_NPROCESSORS_ONLN\012  long count = sysconf(_SC_NPROCESSORS_ONLN);\012  return count < 1 \077 1 : (int64_t)count;\012#else\012  return 1;\012#endif\012}\012\012// Sync (D111 item 4): a lock with two condition variables, for std/channel\012// and std/shared. Its count starts shared (-1), so copies on any thread retain\012// and release it atomically and the share walk stops at it. A Sync is a core\012// (narra_sync_new: the lock, the conditions and two end counts) or an end\012// (narra_sync_end: only the header, pointing at a core). An end adds one to\012// the core's end count of its kind, and when its last copy is dropped it takes\012// that one away again and wakes every waiter of the core, so a channel sees\012// its last sender or its last receiver go. The lock functions take a core.\012typedef struct narra_sync {\012  int64_t rc;\012  struct narra_sync_core* core;\012  int64_t kind;\012} narra_sync;\012\012typedef struct narra_sync_core {\012  narra_sync h;\012  int64_t ends[2];\012  pthread_mutex_t lock;\012  pthread_cond_t ready[2];\012} narra_sync_core;\012\012static narra_sync* narra_sync_new(void) {\012  narra_sync_core* core = narra_alloc(sizeof(narra_sync_core));\012  core->h.rc = -1;\012  core->h.core = NULL;\012  core->h.kind = 0;\012  core->ends[0] = 0;\012  core->ends[1] = 0;\012  pthread_mutex_init(&core->lock, NULL);\012  pthread_cond_init(&core->ready[0], NULL);\012  pthread_cond_init(&core->ready[1], NULL);\012  return &core->h;\012}\012\012// A core whose lock is an error-checking mutex, for std/shared: a second lock\012// by the thread that holds it fails instead of hanging (narra_sync_enter).\012static narra_sync* narra_sync_new_checked(void) {\012  narra_sync* sync = narra_sync_new();\012  narra_sync_core* core = (narra_sync_core*)sync;\012  pthread_mutex_destroy(&core->lock);\012  pthread_mutexattr_t attributes;\012  pthread_mutexattr_init(&attributes);\012  pthread_mutexattr_settype(&attributes, PTHREAD_MUTEX_ERRORCHECK);\012  pthread_mutex_init(&core->lock, &attributes);\012  pthread_mutexattr_destroy(&attributes);\012  return sync;\012}\012\012// Takes the lock of a checked core. Gives true, without the lock, when this\012// thread already holds it, so the caller can stop the program.\012static bool narra_sync_enter(narra_sync* sync) {\012  return pthread_mutex_lock(&((narra_sync_core*)sync)->lock) == EDEADLK;\012}\012\012static void narra_sync_retain(narra_sync* sync) { NARRA_RC_RETAIN(sync->rc); }\012\012static void narra_sync_share(narra_sync* sync) { (void)sync; }\012\012static void narra_sync_lock(narra_sync* sync) {\012  pthread_mutex_lock(&((narra_sync_core*)sync)->lock);\012}\012\012static void narra_sync_unlock(narra_sync* sync) {\012  pthread_mutex_unlock(&((narra_sync_core*)sync)->lock);\012}\012\012static void narra_sync_wait(narra_sync* sync, int64_t condition) {\012  narra_sync_core* core = (narra_sync_core*)sync;\012  pthread_cond_wait(&core->ready[condition & 1], &core->lock);\012}\012\012static void narra_sync_wake_one(narra_sync* sync, int64_t condition) {\012  pthread_cond_signal(&((narra_sync_core*)sync)->ready[condition & 1]);\012}\012\012static void narra_sync_wake_all(narra_sync* sync, int64_t condition) {\012  pthread_cond_broadcast(&((narra_sync_core*)sync)->ready[condition & 1]);\012}\012\012static int64_t narra_sync_ends(narra_sync* sync, int64_t kind) {\012  return ((narra_sync_core*)sync)->ends[kind & 1];\012}\012\012static narra_sync* narra_sync_end(narra_sync* sync, int64_t kind) {\012  narra_sync_core* core = (narra_sync_core*)sync;\012  narra_sync* end = narra_alloc(sizeof(narra_sync));\012  end->rc = -1;\012  narra_sync_retain(sync);\012  end->core = core;\012  end->kind = kind & 1;\012  pthread_mutex_lock(&core->lock);\012  core->ends[end->kind]++;\012  pthread_mutex_unlock(&core->lock);\012  return end;\012}\012\012static void narra_sync_release(narra_sync* sync) {\012  if (!NARRA_RC_RELEASE(sync->rc)) return;\012  narra_sync_core* core = sync->core;\012  if (!core) {\012    core = (narra_sync_core*)sync;\012    pthread_cond_destroy(&core->ready[0]);\012    pthread_cond_destroy(&core->ready[1]);\012    pthread_mutex_destroy(&core->lock);\012    narra_free(core);\012    return;\012  }\012  pthread_mutex_lock(&core->lock);\012  core->ends[sync->kind]--;\012  pthread_cond_broadcast(&core->ready[0]);\012  pthread_cond_broadcast(&core->ready[1]);\012  pthread_mutex_unlock(&core->lock);\012  narra_free(sync);\012  narra_sync_release(&core->h);\012}\012"};
